<?php
declare(strict_types=1);ini_set('session.use_strict_mode','1');session_set_cookie_params(['httponly'=>true,'secure'=>true,'samesite'=>'Strict','path'=>'/']);session_start();header('Content-Type: text/html; charset=UTF-8');header('Cache-Control: no-store');if(($_SESSION['admin_authenticated']??false)!==true){http_response_code(401);exit('Yetkisiz');}
function cv(string $key): string {$file='/var/www/vhosts/mamonestate.com/mamonestate-config.env';foreach(is_readable($file)?file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES):[] as $line){if(str_contains($line,'=')&&!str_starts_with(trim($line),'#')){[$k,$v]=explode('=',$line,2);if(trim($k)===$key)return trim($v," \t\n\r\0\x0B\"'");}}return '';}function dbc(): PDO {$x=parse_url(cv('DATABASE_URL'));if(!$x)throw new RuntimeException('DB eksik');return new PDO(sprintf('pgsql:host=%s;port=%d;dbname=%s',$x['host'],$x['port']??5432,ltrim($x['path'],'/')),urldecode($x['user']??''),urldecode($x['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}function e(string $v): string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function make_slug(string $v): string{$v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',mb_strtolower($v))?:$v;return trim((string)preg_replace('/[^a-z0-9]+/','-',strtolower($v)),'-');}
try{$pdo=dbc();if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim((string)($_POST['title']??''));$region=trim((string)($_POST['region']??''));if($title===''||$region===''){http_response_code(422);exit('Başlık ve bölge zorunlu.');}$slug=make_slug(trim((string)($_POST['slug']??''))?:$title).'-'.substr(bin2hex(random_bytes(3)),0,6);$contract=(string)($_POST['contractType']??'dated');$start=trim((string)($_POST['startDate']??''))?:null;$end=trim((string)($_POST['endDate']??''))?:null;if($contract==='dated'&&(!$start||!$end)){http_response_code(422);exit('Sözleşme tarihlerini girin.');}$sql="insert into listings(region_id,title_tr,description_tr,property_type,sale_type,price_try,rooms,bathrooms,gross_area,cover_image,status,contract_type,contract_start,contract_end,seo_title_tr,seo_description_tr,seo_keywords_tr,slug,canonical_url) select r.id,?,?,?,?,?::numeric,?,nullif(?,'')::smallint,nullif(?,'')::numeric,nullif(?,''),'published',?::contract_kind,?::date,?::date,nullif(?,''),nullif(?,''),nullif(?,''),?,nullif(?,'') from regions r where r.name=? returning id";$s=$pdo->prepare($sql);$s->execute([$title,trim((string)($_POST['description']??'')),(string)($_POST['type']??'Villa'),(string)($_POST['status']??'Satılık'),(string)($_POST['price']??'0'),(string)($_POST['rooms']??''),(string)($_POST['bath']??''),(string)($_POST['area']??''),(string)($_POST['image']??''),$contract,$start,$end,(string)($_POST['seoTitle']??''),(string)($_POST['seoDescription']??''),(string)($_POST['seoKeywords']??''),$slug,(string)($_POST['canonicalUrl']??''),$region]);$id=$s->fetchColumn();if(!$id){http_response_code(422);exit('Bölge bulunamadı.');}header('X-Listing-Id: '.$id);}$rows=$pdo->query("select l.id,l.title_tr,r.name region,l.status::text from listings l join regions r on r.id=l.region_id order by l.created_at desc limit 50")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $row)echo '<div class="mini-listing"><div><b>'.e($row['title_tr']).'</b><small>'.e($row['region']).' · '.e($row['status']).'</small></div><strong>MV-'.(int)$row['id'].'</strong></div>';}catch(Throwable $e){error_log('Admin listings: '.$e->getMessage());http_response_code(500);echo 'İlanlar yüklenemedi.';}
